/** 记录请求打到哪个子路径,并按需给出回复。 */
function stub(reply) {
  const seen = [];
  const f = async (url, init) => { seen.push(String(url)); return reply(String(url), init); };
  f.seen = seen;
  return f;
}

test("1. 非空资源:拿到的是原始字节,不是信封", async () => {
