+ * tempting shortcut is to treat a falsy `content` as "nothing came back" and
+ * throw — the bridge's files/download path does exactly that, folding
+ * `!parsed.data?.content` into its error branch. A zero-byte resource then
+ * reads as a failure. These cases pin the correct behaviour: empty in, empty
+ * Buffer out, and only a real error envelope throws.
+ */
+
+import { test } from "node:test";
+import assert from "node:assert/strict";
+
+import { fetchResource } from "./fetch-resource.mjs";
+
+const BASE = "http://127.0.0.1:8096/skill-bridge/v3/skill";
+
+/** A stub Response whose text() is the given envelope; also records the call. */
+function stub(envelope, calls = []) {
+  return {
+    calls,
+    fetcher: async (url, init) => {
+      calls.push({ url, init, body: JSON.parse(init.body) });
+      return { text: async () => JSON.stringify(envelope) };
+    },
+  };
+}
+
+test("decodes a utf-8 resource to its exact bytes", async () => {
+  const s = stub({ code: 0, message: "ok", data: { content: "hello\n", encoding: "utf-8" } });
+  const bytes = await fetchResource({ skillId: "skl-1", path: "scripts/run.sh", bridgeBase: BASE, fetcher: s.fetcher });
+  assert.ok(Buffer.isBuffer(bytes));
+  assert.equal(bytes.toString("utf-8"), "hello\n");
+  assert.equal(s.calls[0].url, `${BASE}/files/read`);
+  assert.equal(s.calls[0].init.method, "POST");
+  assert.equal(s.calls[0].body.skill_id, "skl-1");
+  assert.equal(s.calls[0].body.path, "scripts/run.sh");
+});
+
+test("decodes a base64 resource to its raw bytes", async () => {
+  const raw = Buffer.from([0x00, 0xff, 0x10, 0x80]);
+  const s = stub({ code: 0, message: "ok", data: { content: raw.toString("base64"), encoding: "base64" } });
+  const bytes = await fetchResource({ skillId: "skl-1", path: "assets/blob.bin", bridgeBase: BASE, fetcher: s.fetcher });
+  assert.deepEqual(bytes, raw);
+});
+
+test("an empty resource is a zero-byte Buffer, not an error", async () => {
+  for (const encoding of ["utf-8", "base64"]) {
+    const s = stub({ code: 0, message: "ok", data: { content: "", size_bytes: 0, encoding } });
